TITLE = "ธัมมจักกัปปวัตตนสูตร"
SUB = "สังยุตตนิกาย มหาวารวรรค (SN 56.11) · ปฐมเทศนา หมุนธรรมจักร ประกาศอริยสัจ ๔"
EXPAND = {
    "sn56.11:4.10": "sammādiṭṭhi sammāsaṅkappo sammāvācā sammākammanto sammāājīvo sammāvāyāmo sammāsati sammāsamādhi.",
    "sn56.11:5.2": "‘Taṁ kho panidaṁ dukkhaṁ ariyasaccaṁ pariññeyyan’ti me, bhikkhave, " + "pubbe ananussutesu dhammesu cakkhuṁ udapādi, ñāṇaṁ udapādi, paññā udapādi, vijjā udapādi, āloko udapādi.",
    "sn56.11:6.2": "‘Taṁ kho panidaṁ dukkhasamudayaṁ ariyasaccaṁ pahātabban’ti me, bhikkhave, " + "pubbe ananussutesu dhammesu cakkhuṁ udapādi, ñāṇaṁ udapādi, paññā udapādi, vijjā udapādi, āloko udapādi.",
    "sn56.11:7.2": "‘Taṁ kho panidaṁ dukkhanirodhaṁ ariyasaccaṁ sacchikātabban’ti me, bhikkhave, " + "pubbe ananussutesu dhammesu cakkhuṁ udapādi, ñāṇaṁ udapādi, paññā udapādi, vijjā udapādi, āloko udapādi.",
    "sn56.11:8.2": "‘Taṁ kho panidaṁ dukkhanirodhagāminī paṭipadā ariyasaccaṁ bhāvetabban’ti me, bhikkhave, " + "pubbe ananussutesu dhammesu cakkhuṁ udapādi, ñāṇaṁ udapādi, paññā udapādi, vijjā udapādi, āloko udapādi.",
    "sn56.11:12.5": "Cātumahārājikānaṁ devānaṁ saddaṁ sutvā tāvatiṁsā devā saddamanussāvesuṁ:\n“etaṁ bhagavatā bārāṇasiyaṁ isipatane migadāye anuttaraṁ dhammacakkaṁ pavattitaṁ, appaṭivattiyaṁ samaṇena vā brāhmaṇena vā devena vā mārena vā brahmunā vā kenaci vā lokasmin”ti.",
    "sn56.11:12.6": "Tāvatiṁsānaṁ devānaṁ saddaṁ sutvā yāmā devā saddamanussāvesuṁ:\n“etaṁ bhagavatā bārāṇasiyaṁ isipatane migadāye anuttaraṁ dhammacakkaṁ pavattitaṁ, appaṭivattiyaṁ samaṇena vā brāhmaṇena vā devena vā mārena vā brahmunā vā kenaci vā lokasmin”ti.",
    "sn56.11:12.7": "Yāmānaṁ devānaṁ saddaṁ sutvā tusitā devā saddamanussāvesuṁ:\n“etaṁ bhagavatā bārāṇasiyaṁ isipatane migadāye anuttaraṁ dhammacakkaṁ pavattitaṁ, appaṭivattiyaṁ samaṇena vā brāhmaṇena vā devena vā mārena vā brahmunā vā kenaci vā lokasmin”ti.",
    "sn56.11:12.8": "Tusitānaṁ devānaṁ saddaṁ sutvā nimmānaratī devā saddamanussāvesuṁ:\n“etaṁ bhagavatā bārāṇasiyaṁ isipatane migadāye anuttaraṁ dhammacakkaṁ pavattitaṁ, appaṭivattiyaṁ samaṇena vā brāhmaṇena vā devena vā mārena vā brahmunā vā kenaci vā lokasmin”ti.",
    "sn56.11:12.9": "Nimmānaratīnaṁ devānaṁ saddaṁ sutvā paranimmitavasavattī devā saddamanussāvesuṁ:\n“etaṁ bhagavatā bārāṇasiyaṁ isipatane migadāye anuttaraṁ dhammacakkaṁ pavattitaṁ, appaṭivattiyaṁ samaṇena vā brāhmaṇena vā devena vā mārena vā brahmunā vā kenaci vā lokasmin”ti.",
}
TH = {
    "1": "สมัยหนึ่ง พระผู้มีพระภาคเจ้าประทับอยู่ที่ป่าอิสิปตนมฤคทายวัน ใกล้เมืองพาราณสี "
         "ณ ที่นั้น พระผู้มีพระภาคเจ้าตรัสกับภิกษุปัญจวัคคีย์ว่า",
    "2": "ภิกษุทั้งหลาย ที่สุดสองอย่างนี้ นักบวชไม่ควรเสพ สองอย่างอะไรบ้าง คือ การหมกมุ่นอยู่กับความสุขในกาม "
         "ซึ่งเป็นของต่ำ เป็นของชาวบ้าน เป็นของปุถุชน ไม่ใช่ของพระอริยะ ไม่มีประโยชน์ อย่างหนึ่ง "
         "และการทรมานตนให้ลำบาก ซึ่งเป็นทุกข์ ไม่ใช่ของพระอริยะ ไม่มีประโยชน์ อีกอย่างหนึ่ง "
         "ภิกษุทั้งหลาย ตถาคตไม่เข้าไปใกล้ที่สุดทั้งสองนั้น ได้ตรัสรู้ทางสายกลาง ซึ่งทำให้มีดวงตา ทำให้เกิดญาณ "
         "เป็นไปเพื่อความสงบ เพื่อความรู้ยิ่ง เพื่อความตรัสรู้ เพื่อนิพพาน",
    "3": "ภิกษุทั้งหลาย ทางสายกลางที่ตถาคตตรัสรู้แล้ว เป็นอย่างไร คืออริยมรรคมีองค์ ๘ นี้เอง ได้แก่ เห็นชอบ ดำริชอบ "
         "พูดชอบ ทำการงานชอบ เลี้ยงชีพชอบ เพียรชอบ ระลึกชอบ ตั้งใจมั่นชอบ ภิกษุทั้งหลาย นี่แหละคือทางสายกลาง "
         "ที่ตถาคตตรัสรู้แล้ว ซึ่งทำให้มีดวงตา ทำให้เกิดญาณ เป็นไปเพื่อความสงบ เพื่อความรู้ยิ่ง เพื่อความตรัสรู้ เพื่อนิพพาน",
    "4": "ภิกษุทั้งหลาย นี่คือทุกขอริยสัจ ความเกิดเป็นทุกข์ ความแก่เป็นทุกข์ ความเจ็บป่วยเป็นทุกข์ ความตายเป็นทุกข์ "
         "การเจอสิ่งที่ไม่รักเป็นทุกข์ การพลัดพรากจากสิ่งที่รักเป็นทุกข์ อยากได้สิ่งใดแล้วไม่ได้สิ่งนั้นก็เป็นทุกข์ "
         "โดยย่อ ขันธ์ ๕ ที่ยึดมั่นไว้เป็นทุกข์ นี่คือทุกขสมุทยอริยสัจ คือตัณหา ความอยากที่พาให้เกิดอีก "
         "มาพร้อมความเพลินและความกำหนัด เพลิดเพลินไปในที่นั้น ๆ ได้แก่ กามตัณหา ภวตัณหา และวิภวตัณหา "
         "นี่คือทุกขนิโรธอริยสัจ คือความดับตัณหานั้นเองโดยสิ้นเชิงไม่เหลือ ความสละ ความวาง ความหลุดพ้น "
         "ความไม่ติดอยู่ นี่คือทุกขนิโรธคามินีปฏิปทาอริยสัจ คืออริยมรรคมีองค์ ๘ นี้เอง ได้แก่ เห็นชอบ ดำริชอบ "
         "พูดชอบ ทำการงานชอบ เลี้ยงชีพชอบ เพียรชอบ ระลึกชอบ ตั้งใจมั่นชอบ",
    "5": "ภิกษุทั้งหลาย ในธรรมที่ไม่เคยได้ยินมาก่อน ดวงตา ญาณ ปัญญา วิชชา และแสงสว่าง ได้เกิดขึ้นแก่เราว่า "
         "นี่คือทุกขอริยสัจ ทุกขอริยสัจนี้ ควรกำหนดรู้ ทุกขอริยสัจนี้ เรากำหนดรู้แล้ว",
    "6": "ภิกษุทั้งหลาย ในธรรมที่ไม่เคยได้ยินมาก่อน ดวงตา ญาณ ปัญญา วิชชา และแสงสว่าง ได้เกิดขึ้นแก่เราว่า "
         "นี่คือทุกขสมุทยอริยสัจ ทุกขสมุทยอริยสัจนี้ ควรละ ทุกขสมุทยอริยสัจนี้ เราละได้แล้ว",
    "7": "ภิกษุทั้งหลาย ในธรรมที่ไม่เคยได้ยินมาก่อน ดวงตา ญาณ ปัญญา วิชชา และแสงสว่าง ได้เกิดขึ้นแก่เราว่า "
         "นี่คือทุกขนิโรธอริยสัจ ทุกขนิโรธอริยสัจนี้ ควรทำให้แจ้ง ทุกขนิโรธอริยสัจนี้ เราทำให้แจ้งแล้ว",
    "8": "ภิกษุทั้งหลาย ในธรรมที่ไม่เคยได้ยินมาก่อน ดวงตา ญาณ ปัญญา วิชชา และแสงสว่าง ได้เกิดขึ้นแก่เราว่า "
         "นี่คือทุกขนิโรธคามินีปฏิปทาอริยสัจ ทุกขนิโรธคามินีปฏิปทาอริยสัจนี้ ควรเจริญ "
         "ทุกขนิโรธคามินีปฏิปทาอริยสัจนี้ เราเจริญแล้ว",
    "9": "ภิกษุทั้งหลาย ตราบใดที่ญาณทัสสนะตามความเป็นจริง ที่หมุนไปสามรอบ มีอาการ ๑๒ ในอริยสัจ ๔ เหล่านี้ "
         "ยังไม่บริสุทธิ์ดีแก่เรา ตราบนั้นเราก็ยังไม่ยืนยันว่าเป็นผู้ตรัสรู้พร้อมซึ่งอนุตตรสัมมาสัมโพธิญาณในโลก "
         "พร้อมทั้งเทวดา มาร พรหม หมู่สัตว์พร้อมทั้งสมณพราหมณ์ เทวดาและมนุษย์",
    "10": "ภิกษุทั้งหลาย แต่เมื่อใด ญาณทัสสนะตามความเป็นจริง ที่หมุนไปสามรอบ มีอาการ ๑๒ ในอริยสัจ ๔ เหล่านี้ "
          "บริสุทธิ์ดีแก่เรา เมื่อนั้นเราจึงยืนยันว่าเป็นผู้ตรัสรู้พร้อมซึ่งอนุตตรสัมมาสัมโพธิญาณในโลก "
          "พร้อมทั้งเทวดา มาร พรหม หมู่สัตว์พร้อมทั้งสมณพราหมณ์ เทวดาและมนุษย์ ญาณทัสสนะได้เกิดขึ้นแก่เราว่า "
          "ความหลุดพ้นของเราไม่กำเริบ ชาตินี้เป็นชาติสุดท้าย บัดนี้ไม่มีภพใหม่อีกต่อไป "
          "พระผู้มีพระภาคเจ้าตรัสคำนี้แล้ว ภิกษุปัญจวัคคีย์ยินดีชื่นชมภาษิตของพระผู้มีพระภาคเจ้า",
    "11": "ก็เมื่อพระผู้มีพระภาคเจ้าตรัสเวยยากรณะนี้อยู่ ธรรมจักษุที่ปราศจากธุลี ปราศจากมลทิน "
          "ได้เกิดขึ้นแก่ท่านโกณฑัญญะว่า สิ่งใดสิ่งหนึ่งมีความเกิดขึ้นเป็นธรรมดา สิ่งนั้นทั้งหมดมีความดับไปเป็นธรรมดา",
    "12": "เมื่อพระผู้มีพระภาคเจ้าทรงหมุนธรรมจักรแล้ว เหล่าภุมมเทวดาป่าวประกาศว่า ธรรมจักรอันยอดเยี่ยมนี้ "
          "พระผู้มีพระภาคเจ้าทรงหมุนแล้ว ที่ป่าอิสิปตนมฤคทายวัน ใกล้เมืองพาราณสี สมณะ พราหมณ์ เทวดา มาร พรหม "
          "หรือใครในโลก ก็หมุนกลับไม่ได้ เทวดาชั้นจาตุมหาราชิกา ดาวดึงส์ ยามา ดุสิต นิมมานรดี ปรนิมมิตวสวัตดี "
          "และพรหมกายิกา ต่างได้ยินเสียงต่อ ๆ กันแล้วก็ป่าวประกาศเช่นเดียวกัน",
    "13": "ด้วยเหตุนี้ ในขณะนั้น ชั่วครู่นั้น เสียงก็ดังขึ้นไปถึงพรหมโลก หมื่นโลกธาตุนี้สั่นสะเทือน หวั่นไหว "
          "สะท้านไปทั่ว และแสงสว่างอันยิ่งใหญ่หาประมาณไม่ได้ ก็ปรากฏขึ้นในโลก เกินกว่าอานุภาพของเทวดาทั้งหลาย",
    "14": "ครั้งนั้น พระผู้มีพระภาคเจ้าทรงเปล่งอุทานว่า โกณฑัญญะได้รู้แล้วหนอ โกณฑัญญะได้รู้แล้วหนอ "
          "เพราะเหตุนี้ ท่านโกณฑัญญะจึงได้ชื่อว่า อัญญาโกณฑัญญะ (จบสูตรที่ ๑)",
}
